import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin

class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.suppressed = 0
        self.href = None
        self.label = []
        self.links = []
        self.text = []

    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.suppressed += 1
        if tag == 'a' and not self.suppressed:
            self.href = dict(attrs).get('href')
            self.label = []

    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.suppressed = max(0, self.suppressed - 1)
        if tag == 'a' and self.href:
            self.links.append((' '.join(' '.join(self.label).split()), self.href))
            self.href = None

    def handle_data(self, data):
        if self.suppressed:
            return
        value = ' '.join(data.split())
        if value:
            self.text.append(value)
            if self.href:
                self.label.append(value)

root = Path('products/services/canadian-public-catalogue-qa-pilot')
source = root / 'raw/walmart-canada-supplier-route.html'
url = 'https://www.walmartcanada.ca/suppliers'
raw = source.read_bytes()
page = Page()
page.feed(raw.decode('utf-8'))
pattern = re.compile(r'become|supplier|vendor|merchandise|service provider|sell to|application|proposal|procurement|contact us', re.I)
quotes = list(dict.fromkeys(text[:650] for text in page.text if pattern.search(text)))[:24]
links = []
for label, href in dict.fromkeys(page.links):
    if label and pattern.search(label + ' ' + href):
        target = urljoin(url, href)
        if target.startswith(('https://', 'http://')):
            links.append({'label': label[:200], 'url': target})
result = {'source_url': url, 'source_sha256': hashlib.sha256(raw).hexdigest(), 'source_artifact': str(source), 'matching_visible_excerpts': quotes, 'matching_link_labels_and_targets': links[:24], 'scope': 'Static HTML excerpts and links. Linked terms, proposal eligibility and buyer interest require separate evidence.'}
output = root / 'walmart-supplier-route-excerpts.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
